?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Consultations | TechSelectAI</title><meta name="robots" content="noindex,nofollow"><style>body{font-family:Inter,Arial,sans-serif;margin:0;background:#f7f9fc;color:#172033}.wrap{max-width:1100px;margin:34px auto;padding:0 20px}.head{display:flex;justify-content:space-between;gap:16px;align-items:center}.head a{color:#123b67}.card{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:18px;margin:14px 0}.meta{color:#64748b;font-size:13px}.problem{line-height:1.55}.top{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.pill{padding:5px 8px;border-radius:999px;background:#eef4f8;font-size:12px}.empty{background:#fff;border:1px dashed #cbd5e1;border-radius:14px;padding:24px}.actions a{display:inline-block;margin-right:8px;margin-top:10px;text-decoration:none;font-weight:700}.new{padding:10px 14px;border-radius:10px;background:#123b67;color:#fff!important}@media(max-width:650px){.head{display:block}.head .new{margin-top:12px}}</style></head><body><main class="wrap"><div class="head"><div><h1>My Consultations</h1><p class="meta">Saved software and technology searches linked to your TechSelectAI account.</p></div><a class="new" href="/">Start new consultation</a></div><div id="content"><p>Loading your consultations…</p></div></main><script>
(async()=>{const box=document.getElementById('content');try{const r=await fetch('/api/account/consultations');const d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to load consultations');const rows=d.consultations||[];if(!rows.length){box.innerHTML='<div class="empty"><h2>No saved consultations yet</h2><p>Start a consultation while signed in, or sign in after an anonymous consultation to attach it to your account.</p><a class="new" href="/">Start software search</a></div>';return;}box.innerHTML=rows.map(c=>{const recs=(c.top_recommendations||[]).map(r=>`<span class="pill">#${Number(r.recommendation_rank)} ${esc(r.name)} · ${Number(r.overall_score).toFixed(0)}%</span>`).join('');return `<article class="card"><div class="meta">${esc(c.category||'Category not confirmed')} · ${esc(c.status)} · Updated ${esc(new Date(c.updated_at).toLocaleString())}</div><h2>${esc(c.title||'Software consultation')}</h2><p class="problem">${esc(c.business_problem)}</p>${recs?`<div class="top">${recs}</div>`:''}<div class="actions"><a href="/?consultation=${encodeURIComponent(c.public_token)}">Reopen consultation</a>${Number(c.recommendation_count)>0?'<span class="meta">Recommendations saved</span>':''}</div></article>`}).join('')}catch(e){box.innerHTML='<div class="empty">'+esc(e.message)+'</div>'}})();function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
